package net.ludovicoflaviano.bettersfp.listener;
import net.ludovicoflaviano.bettersfp.data.*;import net.ludovicoflaviano.bettersfp.gui.SpawnerGui;import org.bukkit.*;import org.bukkit.block.CreatureSpawner;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;import net.ludovicoflaviano.bettersfp.BetterSpawnersPlugin;
public final class SpawnerListener implements Listener {private final BetterSpawnersPlugin plugin;private final SpawnerStore store;private final SpawnerGui gui;private final NamespacedKey key;public SpawnerListener(BetterSpawnersPlugin p,SpawnerStore s,SpawnerGui g){plugin=p;store=s;gui=g;key=new NamespacedKey(p,"entity");}
 @EventHandler public void interact(PlayerInteractEvent e){if(e.getAction()!=org.bukkit.event.block.Action.RIGHT_CLICK_BLOCK||e.getClickedBlock()==null||e.getClickedBlock().getType()!=Material.SPAWNER)return;Player p=e.getPlayer();if(!p.hasPermission("bettersf.use"))return;e.setCancelled(true);SpawnerData d=store.get(e.getClickedBlock().getLocation());if(d==null){CreatureSpawner cs=(CreatureSpawner)e.getClickedBlock().getState();d=new SpawnerData(SpawnerStore.key(e.getClickedBlock().getLocation()),p.getUniqueId(),cs.getSpawnedType().name());store.put(e.getClickedBlock().getLocation(),d);}ItemStack hand=p.getInventory().getItemInMainHand();String held=hand.getItemMeta()==null?null:hand.getItemMeta().getPersistentDataContainer().get(key,PersistentDataType.STRING);if(p.isSneaking()&&held!=null&&held.equalsIgnoreCase(d.entity)&&hand.getType()==Material.SPAWNER){int max=plugin.getConfig().getInt("settings.max-stack",64);if(d.stack<max){int add=Math.min(hand.getAmount(),max-d.stack);d.stack+=add;hand.setAmount(hand.getAmount()-add);p.sendMessage("§aSpawner stacked. §7New stack: §f"+d.stack);store.save();return;}}store.save();gui.open(p,d);}
 @EventHandler public void breakSpawner(BlockBreakEvent e){if(e.getBlock().getType()!=Material.SPAWNER)return;if(!e.getPlayer().hasPermission("bettersf.break"))return;e.setDropItems(false);SpawnerData d=store.get(e.getBlock().getLocation());String entity=d==null?((CreatureSpawner)e.getBlock().getState()).getSpawnedType().name():d.entity;ItemStack it=new ItemStack(Material.SPAWNER);var m=it.getItemMeta();m.setDisplayName("§b"+entity+" Spawner §7x"+(d==null?1:d.stack));m.getPersistentDataContainer().set(key,PersistentDataType.STRING,entity);it.setItemMeta(m);if(d!=null){it.setAmount(Math.min(64,d.stack));}e.getBlock().getWorld().dropItemNaturally(e.getBlock().getLocation(),it);store.remove(e.getBlock().getLocation());store.save();}
 @EventHandler public void place(BlockPlaceEvent e){if(e.getBlockPlaced().getType()!=Material.SPAWNER)return;String entity=e.getItemInHand().getItemMeta().getPersistentDataContainer().get(key,PersistentDataType.STRING);if(entity==null)entity="ZOMBIE";CreatureSpawner cs=(CreatureSpawner)e.getBlockPlaced().getState();try{cs.setSpawnedType(org.bukkit.entity.EntityType.valueOf(entity));cs.update(true,false);}catch(Exception ignored){}SpawnerData d=new SpawnerData(SpawnerStore.key(e.getBlockPlaced().getLocation()),e.getPlayer().getUniqueId(),entity);d.stack=e.getItemInHand().getAmount();store.put(e.getBlockPlaced().getLocation(),d);store.save();}
 @EventHandler public void guiClick(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;SpawnerData d=nearest(p.getLocation());if(d==null)return;if(e.getView().getTitle().equals("§8BetterSpawners §7• §fSpawner"))gui.click(e,d);else if(e.getView().getTitle().equals("§8BetterSpawners §7• §fStorage"))gui.storageClick(e,d);}
 private SpawnerData nearest(Location l){SpawnerData best=null;double dist=64;for(SpawnerData d:store.all().values()){Location x=SpawnerStore.location(d.key);if(x!=null&&x.getWorld()==l.getWorld()){double q=x.distanceSquared(l);if(q<dist){dist=q;best=d;}}}return best;}}
